architecture.h4_f:
msg = CBOR{v:1, matn, javob berish, yuborilgan_at}
ct = AES-GCM-256-shifrlash(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {shifrlangan matn: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, matn, javob_to'plash?, mavzu_id?, eslatib o'tish?, sent_at}
ct = AES-GCM-256-shifrlash(xona_kalit, nonce, pt, aad=hex(xona_identifikatori))
sim = CBOR{
  v: 1,
  shifrlangan matn: hex(ct), // o'zgaruvchan uzunlik
  bo'lmagan: hex (12 B),
  sender_pseudo: hex (16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
tashqi = CBOR{
  manba_tugun: hex32,
  target_user: int64,
  ichki_shifrlangan matn: baytlar,
  ichki_noce: baytlar,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, tashqi)
POST /federatsiya/deliver { konvert: tashqi, sig: hex64 }

auth.h1_f:
POST /api/autentifikatsiya/roʻyxatdan oʻtish
  { foydalanuvchi nomi, parol, x25519_public_key, displey_nomi, telefon?, email?, avatar_emoji }

201-javob yaratilgan:
  { access_token, refresh_token, user_id, username, ...}

auth.h3_f:
access_token yuki:
  { sub: user_id, jti: device_id, yozing: "kirish", ekspluatatsiya: hozir + 15 daqiqa}
refresh_token foydali yuki:
  { sub: user_id, jti: device_id, yozing: "yangilash", ekspluatatsiya: hozir + 30 kun }

HS256-.env dan tugunning 64 baytlik siri bilan imzolangan

auth.h4_f:
register_begin(): muammo = rand(32)
                    variantlar = {rp.id, user.id, pubKeyCredParams, challenge }
                    qaytarish variantlari

register_finish(attestatsiya):
  attestatsiyani TPM / Secure Enclave root CA bilan tasdiqlang
  do'kon {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR foydali yuk = {nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { bir marta }
  → yangi qurilma ro'yxatga olingan; JWTs qaytib keldi.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(xona_pseudo_tuz, sender_id)[:16] // 32 hex
shifrlangan matn = AES-GCM-shifrlash(xona_kalit, nonce, CBOR_payload, aad=xona_identifikatori)

Fan-out freym: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {fayl nomi, hajmi, chunk_size_hint}
            ← {yuklash_identifikatori, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bayt>
            ← 204
yakunlash POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL tugallanmagan: 24 soat

files.h4_f:
rad etish_ro'yxati = {
  "ilova/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
agar magic.from_buffer(buf[:1024]) inkor etilgan_roʻyxatda: 415-ni qaytaring

presence.h1_f:
mijoz: birinchi bosishda → yuboring {type:"t", state:"start"}
         holati o'zgarmasa, endi 3 soniya davomida yuborilmaydi
         Klaviaturani oxirgi marta bosgandan keyin 10 s → yuboring {type:"t", state:"stop"}
qabul qilgich: agar "to'xtash" kelmasa, oxirgi "start"dan 10 soniya o'tgach avtomatik to'xtash

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS translyatsiya {turi:"c", turdagi:"invite", call_id}
WS translyatsiya {turi:"c", turdagi:"taklif", sdp}
WS translyatsiya {turi:"c", turdagi:"javob", sdp}
WS translyatsiya {turi:"c", turdagi:"nomzod",muz} × N
POST /api/calls/{call_id}/end

federation.h2_f:
konvert = {
  manba_tugun: hex32,
  target_user: int64,
  ichki_shifrlangan matn: baytlar,
  ichki_nonce: baytlar,
  sent_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(konvert))
POST /federatsiya/deliver { konvert, sig }

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nomi: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni (ommaviy_kalit_from_HTTPS_record)
DGA: domen(t) = tayanch32( SHA256(urugʻ ∥ YYYY-MM-DD) )[:16] + ".misol"

push.h4_f:
iOS NSE: didReceive(so'rov) { shifrini ochish(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { shifrini ochish(remoteMessage.data) }
Veb SW: self.addEventListener('push', e => shifrni ochish(e.data))

controller.h2_f:
asbob = sign_tool
kirish = manba daraxti, kalitlar/release.key
manifest = {
  versiya: "0.1.0",
  qurilgan_: unix_ms,
  fayllar: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
chiqish = INTEGRITY.sig.json = {manifest, imzolangan_by: pub_hex, sig: sig_hex}

bots.h1_f:
yaratish: POST /api/bots {foydalanuvchi nomi, displey_nomi, kod}
          → {bot_id, token, pubkey}
ishga tushirish: jarayonda (tugun ichidagi koroutin)
      OR tashqi (uzoq so'rov /api/bots/{id}/yangilanishlar, token-auth'd)
xabar: {matn, imzo: Ed25519-Sign(bot_priv, canonical_msg)}

security.h4_f:
canary.txt (kunlik):
  {sana, belgi: Ed25519-Sign(release_priv, sana)}
mijoz tasdiqlaydi → yo'q yoki noto'g'ri ⇒ murosaga shubha qilingan

favqulodda holat:
  admin POST /api/admin/revoke-all {sabab}
  tugun translyatsiyalari {turi:"n", voqea:"murosa", sabab}
  mijozlar kalitlarni o'chiradi, qayta yuklashni majbur qiladi

