fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  kontent, -- tokenlashtirilgan ustun
  xonaning identifikatori UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
so'rov: SELECT rowid FROM messages_fts WHERE kontent MATCH 'foo'

gravitix.h1_f:
/start { emit "Xush kelibsiz, {ctx.first_name}" }
/ qo'shish <element> {
  state.list = (state.list yoki []) + [ctx.args.item]
  emit "Qo'shilgan: {ctx.args.item}"
}

prekey.h1_f:
to'plam = {
  identity_pk,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-Sign(identity_priv, signed_prekey_pk),
  bir martalik_prekeys: [pk_0, pk_1, ..., pk_9]
}

